-- Fix ambiguous PL/pgSQL output parameter "id" in exam answer RPC.\n-- The RPC must qualify the target row alias because RETURNS TABLE exposes an id variable.\nCREATE OR REPLACE FUNCTION public.save_exam_attempt_answers(p_legacy_id text, p_answers jsonb, p_answers_updated_at timestamptz, p_status text, p_client_revision bigint DEFAULT 0)\nRETURNS TABLE(id uuid, legacy_id text, answers jsonb, answers_updated_at timestamptz, answers_revision bigint, status text, submitted_at timestamptz)\nLANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public' AS $$\ndeclare\n  v_attempt public.exam_attempts%rowtype;\n  v_revision bigint; v_updated timestamptz; v_status text; v_key text; v_value jsonb; v_question_id uuid;\nbegin\n  select a.* into v_attempt from public.exam_attempts a where a.legacy_id=p_legacy_id for update;\n  if not found then raise exception 'EXAM_ATTEMPT_NOT_FOUND' using errcode='P0002'; end if;\n  if v_attempt.status='submitted' or v_attempt.submitted_at is not null then\n    return query select v_attempt.id,v_attempt.legacy_id,v_attempt.answers,v_attempt.answers_updated_at,v_attempt.answers_revision,v_attempt.status,v_attempt.submitted_at; return;\n  end if;\n  if p_answers_updated_at is not null and v_attempt.answers_updated_at is not null and p_answers_updated_at < v_attempt.answers_updated_at and coalesce(p_client_revision,0) <= coalesce(v_attempt.answers_revision,0) then\n    return query select v_attempt.id,v_attempt.legacy_id,v_attempt.answers,v_attempt.answers_updated_at,v_attempt.answers_revision,v_attempt.status,v_attempt.submitted_at; return;\n  end if;\n  v_revision:=greatest(coalesce(v_attempt.answers_revision,0)+1,coalesce(p_client_revision,0));\n  v_updated:=greatest(coalesce(p_answers_updated_at,now()),coalesce(v_attempt.answers_updated_at,now()));\n  v_status:=case when p_status in ('submitted','expired','cancelled','in_progress') then p_status else 'in_progress' end;\n  update public.exam_attempts as ea set answers=coalesce(p_answers,'{}'::jsonb),answers_updated_at=v_updated,answers_revision=v_revision,status=case when v_status='submitted' then 'submitted' else ea.status end,submitted_at=case when v_status='submitted' then coalesce(ea.submitted_at,now()) else ea.submitted_at end,updated_at=now() where ea.id=v_attempt.id returning ea.* into v_attempt;\n  for v_key,v_value in select key,value from jsonb_each(coalesce(p_answers,'{}'::jsonb)) loop\n    select q.id into v_question_id from public.exam_questions q where q.exam_id=v_attempt.exam_id and q.legacy_id=v_key limit 1;\n    if v_question_id is not null then\n      insert into public.attempt_answers(attempt_id,question_id,answer,revision,client_updated_at,updated_at) values(v_attempt.id,v_question_id,v_value,v_revision,p_answers_updated_at,now()) on conflict(attempt_id,question_id) do update set answer=excluded.answer,revision=excluded.revision,client_updated_at=excluded.client_updated_at,updated_at=excluded.updated_at where public.attempt_answers.revision <= excluded.revision;\n    end if;\n  end loop;\n  insert into public.exam_events(attempt_id,exam_id,discord_id,event_type,metadata) values(v_attempt.id,v_attempt.exam_id,v_attempt.discord_id,'ANSWER_SNAPSHOT_SAVED',jsonb_build_object('revision',v_revision,'answer_count',(select count(*) from jsonb_object_keys(coalesce(p_answers,'{}'::jsonb)))));\n  return query select v_attempt.id,v_attempt.legacy_id,v_attempt.answers,v_attempt.answers_updated_at,v_attempt.answers_revision,v_attempt.status,v_attempt.submitted_at;\nend; $$;\n\nCREATE OR REPLACE FUNCTION public.save_exam_attempt_answers(p_legacy_id text, p_answers jsonb, p_answers_updated_at timestamptz, p_status text)\nRETURNS TABLE(id uuid, legacy_id text, answers jsonb, answers_updated_at timestamptz, answers_revision bigint, status text, submitted_at timestamptz)\nLANGUAGE sql SECURITY DEFINER SET search_path TO 'public' AS $$ SELECT * FROM public.save_exam_attempt_answers(p_legacy_id,p_answers,p_answers_updated_at,p_status,0::bigint); $$;